        {
            RuleFor(x => x.Email)
                .NotEmpty()
                .Must(AuthenticationLogic.IsValidEmail)
                .WithMessage("Invalid email format");

            RuleFor(x => x.Password)
                .NotEmpty()
                .Must(AuthenticationLogic.IsValidPassword)
                .WithMessage("Password must be at least 8 characters with uppercase, lowercase and digit");
        }
    }

    public sealed class DiscountRequestValidator : AbstractValidator<DiscountRequest>
    {
        public DiscountRequestValidator()
        {
            RuleFor(x => x.Age)
                .GreaterThanOrEqualTo(0)
                .LessThanOrEqualTo(120);

            RuleFor(x => x.Amount)
                .GreaterThanOrEqualTo(0);
        }
    }

