        public async Task<AuthResponse> AuthenticateUserAsync(AuthRequest request)
        {
            var validation = await _authValidator.ValidateAsync(request);
            if (!validation.IsValid)
            {
                throw new ValidationException(validation.Errors);
            }

            bool isAuthenticated = _options.Value.AllowTestAdmin && 
                CredentialLogic.IsTestAdmin(request.Email, request.Password);

            if (!isAuthenticated)
            {
